export const GLSL_NOISE="\nfloat hash31(vec3 p){ p = fract(p * 0.1031); p += dot(p, p.zyx + 31.32); return fract((p.x + p.y) * p.z); }\nfloat vnoise(vec3 p){ vec3 i = floor(p), f = fract(p); f = f*f*(3.0 - 2.0*f);\n  return mix(mix(mix(hash31(i), hash31(i+vec3(1,0,0)), f.x), mix(hash31(i+vec3(0,1,0)), hash31(i+vec3(1,1,0)), f.x), f.y),\n             mix(mix(hash31(i+vec3(0,0,1)), hash31(i+vec3(1,0,1)), f.x), mix(hash31(i+vec3(0,1,1)), hash31(i+vec3(1,1,1)), f.x), f.y), f.z); }\nfloat fbm(vec3 p){ return 0.5*vnoise(p) + 0.3*vnoise(p*2.13) + 0.2*vnoise(p*4.31); }\n";
export const VS_FULL="#version 300 es\nprecision highp float; precision highp int; precision highp sampler2D; precision highp sampler2DArray;\n\nvoid main(){ vec2 p = vec2(float((gl_VertexID << 1) & 2), float(gl_VertexID & 2)); gl_Position = vec4(p*2.0 - 1.0, 0.0, 1.0); }";
export const FS_FORCE="#version 300 es\nprecision highp float; precision highp int; precision highp sampler2D; precision highp sampler2DArray;\n\nuniform sampler2D uPos; uniform ivec2 uSize;\nuniform float uG, uEps2, uK, uRmax;\nout vec4 oInfo;                         // xyz = acceleration, w = index of the body that absorbs me (-1 = none) [+0.5: I have something to absorb]\nvoid main(){\n  ivec2 me = ivec2(gl_FragCoord.xy);\n  vec4 pi = texelFetch(uPos, me, 0);\n  if (pi.w <= 0.0) { oInfo = vec4(0.0, 0.0, 0.0, -1.0); return; }\n  int myIdx = me.y * uSize.x + me.x;\n  float ri = uK * pow(pi.w, 1.0/3.0);\n  float nearR = ri + uRmax, near2 = nearR * nearR;\n  vec3 acc = vec3(0.0);\n  float bestM = -1.0; int best = -1; bool prey = false;\n  for (int y = 0; y < uSize.y; y++) {\n    for (int x = 0; x < uSize.x; x++) {\n      vec4 pj = texelFetch(uPos, ivec2(x, y), 0);\n      vec3 d = pj.xyz - pi.xyz;\n      float d2 = dot(d, d);\n      float inv = inversesqrt(d2 + uEps2);\n      acc += d * (pj.w * inv * inv * inv);          // dead body: mass 0 → adds 0; self: d = 0 → adds 0\n      if (d2 < near2 && pj.w > 0.0) {\n        int j = y * uSize.x + x;\n        if (j != myIdx) {\n          float rr = ri + uK * pow(pj.w, 1.0/3.0);\n          if (d2 < rr * rr) {                        // contact!\n            bool jBigger = (pj.w > pi.w) || (pj.w == pi.w && j < myIdx);\n            if (jBigger) { if (pj.w > bestM) { bestM = pj.w; best = j; } }\n            else prey = true;\n          }\n        }\n      }\n    }\n  }\n  oInfo = vec4(acc * uG, float(best) + (prey ? 0.5 : 0.0));\n}";
export const FS_INTEGRATE="#version 300 es\nprecision highp float; precision highp int; precision highp sampler2D; precision highp sampler2DArray;\n\nuniform sampler2D uPos, uVel, uCol, uInfo; uniform ivec2 uSize;\nuniform float uDt, uFlashDecay, uGas, uG, uGM; uniform vec3 uStarPos;\nlayout(location=0) out vec4 oPos;       // xyz, mass\nlayout(location=1) out vec4 oVel;       // xyz, collision flash\nlayout(location=2) out vec4 oCol;       // rgb, seed\nvoid main(){\n  ivec2 me = ivec2(gl_FragCoord.xy);\n  vec4 p = texelFetch(uPos, me, 0), v = texelFetch(uVel, me, 0), c = texelFetch(uCol, me, 0);\n  if (p.w <= 0.0) { oPos = vec4(p.xyz, 0.0); oVel = vec4(0.0); oCol = c; return; }\n  vec4 info = texelFetch(uInfo, me, 0);\n  float tf = floor(info.w); int target = int(tf); bool prey = (info.w - tf) > 0.25;\n  if (target >= 0) {\n    float ti = texelFetch(uInfo, ivec2(target % uSize.x, target / uSize.x), 0).w;\n    if (floor(ti) < 0.0) { oPos = vec4(p.xyz, 0.0); oVel = vec4(0.0); oCol = c; return; }   // my absorber survives → I am gone\n  }\n  float m = p.w; vec3 mp = p.xyz * m, mv = v.xyz * m, mc = c.rgb * m, ma = info.xyz * m;\n  float flash = v.w * uFlashDecay;\n  if (prey && target < 0) {\n    int myIdx = me.y * uSize.x + me.x; float eaten = 0.0;\n    for (int y = 0; y < uSize.y; y++) for (int x = 0; x < uSize.x; x++) {\n      ivec2 tc = ivec2(x, y);\n      vec4 ij = texelFetch(uInfo, tc, 0);\n      if (int(floor(ij.w)) == myIdx) {\n        vec4 pj = texelFetch(uPos, tc, 0);\n        if (pj.w > 0.0) {\n          mp += pj.xyz * pj.w; mv += texelFetch(uVel, tc, 0).xyz * pj.w; mc += texelFetch(uCol, tc, 0).rgb * pj.w;\n          ma += ij.xyz * pj.w;           // sum the FORCES too: the mutual pull between merging bodies cancels, momentum is conserved\n          eaten += pj.w;\n        }\n      }\n    }\n    if (eaten > 0.0) flash = max(flash, clamp(0.25 + 2.5 * eaten / m, 0.0, 1.0));\n    m += eaten;\n  }\n  vec3 pos = mp / m, vel = mv / m;\n  vel += (ma / m) * uDt;                 // kick\n  vec3 rel = pos - uStarPos; float rc = length(rel.xz);\n  if (uGas > 0.0 && m * uG < uGM * 0.2 && rc > 2.0) {   // nebular gas on circular orbits around the star drags the planets (never the star) along\n    vec3 vg = vec3(-rel.z, 0.0, rel.x) * (sqrt(uGM / length(rel)) / rc);\n    vel += (vg - vel) * min(uGas * uDt, 1.0);\n  }\n  pos += vel * uDt;                      // drift  (semi-implicit Euler: symplectic, orbits do not leak energy)\n  oPos = vec4(pos, m); oVel = vec4(vel, flash); oCol = vec4(mc / m, c.w);\n}";
export const VS_BODY="#version 300 es\nprecision highp float; precision highp int; precision highp sampler2D; precision highp sampler2DArray;\n\nuniform sampler2D uPos, uVel, uCol; uniform ivec2 uSize;\nuniform mat4 uView, uProj; uniform vec2 uViewport;\nuniform float uK, uMinPx, uTotalMass, uStarFrac; uniform vec3 uSunPos; uniform int uHalo;\nout vec2 vUv; flat out vec4 vCol; flat out vec4 vParam; flat out vec3 vLight; flat out vec3 vStar; flat out vec3 vGlow;\nvec3 starColor(float f){                      // by mass fraction: red dwarf → orange → yellow → warm white\n  float x = clamp((log(f) / log(10.0) + 2.0) / 1.7, 0.0, 1.0);\n  vec3 a = vec3(1.0, 0.33, 0.13), b = vec3(1.0, 0.62, 0.28), c = vec3(1.0, 0.86, 0.60), d = vec3(1.0, 0.95, 0.84);\n  return x < 0.33 ? mix(a, b, x / 0.33) : (x < 0.66 ? mix(b, c, (x - 0.33) / 0.33) : mix(c, d, (x - 0.66) / 0.34));\n}\nvoid main(){\n  int id = gl_InstanceID; ivec2 tc = ivec2(id % uSize.x, id / uSize.x);\n  vec4 p = texelFetch(uPos, tc, 0);\n  vUv = vec2(0.0); vCol = vec4(0.0); vParam = vec4(0.0); vLight = vec3(0.0, 0.0, 1.0); vStar = vec3(0.0); vGlow = vec3(0.0);\n  if (p.w <= 0.0) { gl_Position = vec4(2.0, 2.0, 2.0, 1.0); return; }\n  vec4 c = texelFetch(uCol, tc, 0); float flash = texelFetch(uVel, tc, 0).w;\n  vec2 corner = vec2(float(gl_VertexID & 1), float((gl_VertexID >> 1) & 1)) * 2.0 - 1.0;\n  vec4 vp = uView * vec4(p.xyz, 1.0);\n  float r = uK * pow(p.w, 1.0/3.0);\n  float pxPerUnit = uProj[1][1] * uViewport.y * 0.5 / max(-vp.z, 1e-3);\n  float rPx = r * pxPerUnit;\n  float rDraw = max(rPx, uMinPx) / pxPerUnit;\n  float frac = p.w / uTotalMass;\n  float heat = smoothstep(uStarFrac * 0.6, uStarFrac * 1.5, frac);\n  float lump = 0.34 * (1.0 - smoothstep(0.8, 14.0, p.w));          // small bodies are lumpy; they round out as they grow\n  vec3 star = starColor(frac);\n  float scale = 1.0;\n  if (uHalo == 1) {\n    scale = mix(3.2, 5.5, heat) * (1.0 + 1.6 * flash);\n    vGlow = mix(c.rgb * 0.30, star * 0.7, heat) + flash * vec3(1.0, 0.55, 0.22) * 1.3;\n    vGlow *= clamp(rPx / uMinPx, 0.45, 1.0);\n  }\n  vUv = corner * (uHalo == 1 ? 1.0 : 1.06);\n  vCol = c; vParam = vec4(max(rPx, uMinPx), heat, flash, lump); vStar = star;\n  vec3 sunV = (uView * vec4(uSunPos, 1.0)).xyz - vp.xyz;\n  vLight = length(sunV) > 1e-3 ? normalize(sunV) : vec3(0.0, 0.0, 1.0);\n  vp.xy += corner * rDraw * scale * (uHalo == 1 ? 1.0 : 1.06);\n  gl_Position = uProj * vp;\n}";
export const FS_BODY="#version 300 es\nprecision highp float; precision highp int; precision highp sampler2D; precision highp sampler2DArray;\n\nfloat hash31(vec3 p){ p = fract(p * 0.1031); p += dot(p, p.zyx + 31.32); return fract((p.x + p.y) * p.z); }\nfloat vnoise(vec3 p){ vec3 i = floor(p), f = fract(p); f = f*f*(3.0 - 2.0*f);\n  return mix(mix(mix(hash31(i), hash31(i+vec3(1,0,0)), f.x), mix(hash31(i+vec3(0,1,0)), hash31(i+vec3(1,1,0)), f.x), f.y),\n             mix(mix(hash31(i+vec3(0,0,1)), hash31(i+vec3(1,0,1)), f.x), mix(hash31(i+vec3(0,1,1)), hash31(i+vec3(1,1,1)), f.x), f.y), f.z); }\nfloat fbm(vec3 p){ return 0.5*vnoise(p) + 0.3*vnoise(p*2.13) + 0.2*vnoise(p*4.31); }\n\nin vec2 vUv; flat in vec4 vCol; flat in vec4 vParam; flat in vec3 vLight; flat in vec3 vStar; flat in vec3 vGlow;\nuniform float uTime, uSunLit; out vec4 o;\nvoid main(){\n  float seed = vCol.w, rPx = vParam.x, heat = vParam.y, flash = vParam.z, lump = vParam.w;\n  float ang = atan(vUv.y, vUv.x);\n  float sil = 1.0 - lump * (0.5 + 0.3 * sin(ang * 2.0 + seed * 50.0) + 0.2 * sin(ang * 5.0 + seed * 91.0));\n  float d = length(vUv) / sil;\n  float aa = clamp(1.5 / rPx, 0.02, 0.9);\n  float alpha = 1.0 - smoothstep(1.0 - aa, 1.0, d);\n  if (alpha <= 0.004) discard;\n  float z = sqrt(max(1.0 - min(d * d, 1.0), 0.0));\n  vec3 n = normalize(vec3(vUv / sil, z + 1e-4));\n  vec3 base = vCol.rgb, surf = base; float gran = 0.5;\n  if (rPx > 3.0) {                                           // surface detail when seen up close\n    float tilt = (fract(seed * 5.3) - 0.5) * 1.2, ct = cos(tilt), st = sin(tilt);\n    vec3 q = vec3(ct * n.x - st * n.y, st * n.x + ct * n.y, n.z);\n    float a = uTime * (0.15 + fract(seed * 13.7) * 0.4) + seed * 100.0, ca = cos(a), sa = sin(a);\n    q = vec3(ca * q.x + sa * q.z, q.y, -sa * q.x + ca * q.z);\n    float kind = fract(seed * 7.31), t = fbm(q * 2.4 + seed * 17.0);\n    gran = fbm(q * 7.0 + vec3(0.0, uTime * 0.15, seed * 9.0));\n    if (kind < 0.45)      surf = base * (0.5 + 1.0 * t);                                   // rocky\n    else if (kind < 0.75) { float b = sin(q.y * 9.0 + t * 5.0 + seed * 30.0); surf = base * (0.82 + 0.24 * b) + vec3(0.05, 0.025, 0.0) * b; }   // gas giant\n    else if (kind < 0.90) { float land = smoothstep(0.50, 0.56, t);                          // ocean + land + polar caps\n      surf = mix(base * vec3(0.55, 0.8, 1.15), base.grb * vec3(0.75, 0.9, 0.5) + 0.08, land);\n      surf = mix(surf, vec3(0.95), smoothstep(0.78, 0.92, abs(q.y))); }\n    else                  surf = mix(base, vec3(0.92, 0.97, 1.0), 0.2 + 0.6 * t);           // ice\n  }\n  float head = 0.38 + 0.62 * z;\n  float sun = 0.10 + 1.0 * max(dot(n, vLight), 0.0);\n  vec3 planet = surf * mix(head, sun, uSunLit);\n  vec3 starC = vStar * (0.80 + 0.45 * z) * (0.85 + 0.35 * gran) * 1.35;\n  vec3 c = mix(planet, starC, heat) + flash * vec3(1.0, 0.6, 0.25) * 0.9;\n  o = vec4(c * alpha, alpha);\n}";